type Envelope struct { Body Payload; Slip []string; Cursor int }
type Step func(context.Context, *Envelope) error

func advance(ctx context.Context, e *Envelope, r map[string]Step) error {
    for e.Cursor < len(e.Slip) {
        if err := r[e.Slip[e.Cursor]](ctx, e); err != nil {
            return err   // caller retries, compensates or dead-letters
        }
        e.Cursor++
    }
    return nil
}
